    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address newOwner, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        uint256 beforeBalance = address(c).balance;
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.transferOwnership(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            (reverted && c.owner() == beforeOwner) ||
            (!reverted && c.owner() == newOwner) ||
            (reverted == false)
        );
    }

    receive() external payable {}
}

