        c = new Owned();
    }

    function _run(address newOwner, uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        uint256 beforeBalance = address(c).balance;
        address beforeOwner;
        try c.owner() returns (address __r) { beforeOwner = __r; } catch { return; }
        bool reverted;
        try c.transferOwnership(newOwner) {
